//! Typed view of `schema/formats.json`.
//!
//! Generated by `tools/extract-formats.py` from `src/serialization/`, and embedded at compile
//! time.  It says, for each of the three interchange formats, what each record is called in the
//! file, which fields it has, where each one lives, and which model property it feeds.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct FormatData {
    pub generated_by: String,
    pub formats: BTreeMap<String, Format>,
    /// Properties a format writes out that the database does not store, because they are
    /// calculated -- a recipe's ABV, a fermentable's colour in SRM.
    pub properties_not_stored_in_the_schema: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Format {
    pub source_file: String,
    /// The tables mapping this format's unit names onto ours, by the name the C++ gives them.
    pub unit_mappings: BTreeMap<String, UnitMapping>,
    pub records: Vec<Record>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum UnitMapping {
    /// A unit name in the file mapped to the name of one of ours.
    Units { units: BTreeMap<String, String> },
    /// A field always in one unit, named so it can be written back out.
    SingleUnit { names: Vec<String> },
    /// A field that may use any unit from several tables, e.g. a mass or a volume.
    AnyOf { mappings: Vec<String> },
}

#[derive(Debug, Clone, Deserialize)]
pub struct Record {
    /// The C++ name of the definition, e.g. `DOT_BEER_RECORD_DEFN`.
    pub name: String,
    /// The entity this record stores, e.g. `Hop`.
    pub cpp_type: String,
    /// What the record is called in the file, e.g. `hops`.
    pub record_name: String,
    pub fields: Vec<Field>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Field {
    /// `String`, `Enum`, `MeasurementWithUnits`, `ListOfRecords`, and so on.
    pub field_type: String,
    /// Where the value sits in the record, `/`-separated for a nested one.
    pub path: String,
    /// The model property this feeds, `None` for fields that are structural only and for fields
    /// that name a path of properties rather than one.
    pub property: Option<String>,
    /// The chain of properties this field feeds, where it names more than one.
    ///
    /// BeerXML has no `Boil` record, so a recipe's `BOIL_TIME` is "the boil time of the recipe's
    /// boil": the boil is something the reader has to create.  Only BeerXML does this, and only
    /// on a recipe.
    #[serde(default)]
    pub property_path: Option<Vec<String>>,
    /// The enum mapping, unit table, nested record or validator this field uses.
    pub decoder: Option<String>,
    /// Set when `decoder` names another record definition.
    pub nested_record_type: Option<String>,
    pub validator: Option<String>,
}

const FORMATS_JSON: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../schema/formats.json"));

/// The format definitions, parsed once.
///
/// # Panics
///
/// If the embedded JSON does not match these types, which is a build-time inconsistency between
/// `tools/extract-formats.py` and this crate.
pub fn format_data() -> &'static FormatData {
    static DATA: OnceLock<FormatData> = OnceLock::new();
    DATA.get_or_init(|| {
        serde_json::from_str(FORMATS_JSON).expect("schema/formats.json does not match bt_format::FormatData")
    })
}

impl FormatData {
    pub fn format(&self, name: &str) -> Option<&Format> {
        self.formats.get(name)
    }
}

impl Format {
    /// The record a collection in the file corresponds to, e.g. `hops`.
    pub fn record_named(&self, record_name: &str) -> Option<&Record> {
        self.records.iter().find(|record| record.record_name == record_name)
    }

    /// The record that stores a given entity, e.g. `Hop`.
    ///
    /// Several records may store the same entity -- a hop on its own and a hop embedded in a
    /// recipe addition are different shapes -- so this takes the first, which is the standalone
    /// one.
    pub fn record_for(&self, cpp_type: &str) -> Option<&Record> {
        self.records.iter().find(|record| record.cpp_type == cpp_type)
    }
}
